const OPT = {
  '[BU AIchat] ChatbotOnline': '11036', '[BU AIchat] UniCopy': '10151',
  '[BU Mobi] Mobitrace': '10154', '[BU Mobi] MyImage': '10155', '[BU Mobi] RealChecker': '11839', '[BU Mobi] VinReady': '10644',
  '[BU PDF] PDFhelp': '10157',
  '[BU Perso] BrainIQtest': '10152', '[BU Perso] LoveStyle': '10153', '[BU Perso] MindSpree': '11003', '[BU Perso] Personality': '10158',
  '[BU QR] QRcenter': '12209', '[BU QR] QRcreate': '11002', '[BU QR] MyQRCode': '10156',
  '[BU Resume] MyWapp': '10160', '[BU Resume] ResumeWise': '10159',
  '[BU UniCopy] Scannerly': '10900',
  '[IU Internationalization]': '10777'
};
const ALIAS = { '[BU UniCopy] UniCopy': '[BU AIchat] UniCopy' };
const KEYMAP = {
  AICHAT: '[BU AIchat] ChatbotOnline', UNICOPY: '[BU AIchat] UniCopy',
  MOBITR: '[BU Mobi] Mobitrace', MYIMAGE: '[BU Mobi] MyImage', REALCHECK: '[BU Mobi] RealChecker', VIN: '[BU Mobi] VinReady',
  PDFHELP: '[BU PDF] PDFhelp', IQTST: '[BU Perso] BrainIQtest', LOVE: '[BU Perso] LoveStyle', PERSO: '[BU Perso] Personality',
  MYQRCODE: '[BU QR] MyQRCode', QRCREATE: '[BU QR] QRcreate',
  WAPP: '[BU Resume] MyWapp', RESUME: '[BU Resume] ResumeWise', SCAN: '[BU UniCopy] Scannerly'
};
const WORDS = [
  [/mindspree/i, '[BU Perso] MindSpree'],
  [/personality/i, '[BU Perso] Personality'],
  [/brain\s*iq|iq\s*test/i, '[BU Perso] BrainIQtest'],
  [/love\s*(style|language)/i, '[BU Perso] LoveStyle'],
  [/real\s*checker/i, '[BU Mobi] RealChecker'],
  [/mobitrace/i, '[BU Mobi] Mobitrace'],
  [/my\s*image/i, '[BU Mobi] MyImage'],
  [/vin\s*(checker|ready)/i, '[BU Mobi] VinReady'],
  [/pdf\s*(editor|help)/i, '[BU PDF] PDFhelp'],
  [/qr\s*create/i, '[BU QR] QRcreate'],
  [/qr\s*center/i, '[BU QR] QRcenter'],
  [/my\s*qr\s*code/i, '[BU QR] MyQRCode'],
  [/resume\s*wise/i, '[BU Resume] ResumeWise'],
  [/my\s*wapp|\bwapp\b/i, '[BU Resume] MyWapp'],
  [/scannerly/i, '[BU UniCopy] Scannerly'],
  [/uni\s*copy/i, '[BU AIchat] UniCopy'],
  [/chatbot|chat\s*ai|ai\s*chat/i, '[BU AIchat] ChatbotOnline']
];

const issues = $('One item per ticket').all();
const parents = $input.all();
const out = [];

for (let i = 0; i < issues.length; i++) {
  const issue = issues[i].json;
  const f = issue.fields || {};
  const summary = f.summary || '';
  let name = null;
  let source = null;

  if (f.parent) {
    const pf = (parents[i] && parents[i].json && parents[i].json.fields) || {};
    const pv = pf.customfield_10205;
    if (pv && pv.value && OPT[pv.value]) { name = pv.value; source = 'parent ' + f.parent.key; }
  }

  if (!name) {
    let best = null, bestPos = -1;
    for (const cand of Object.keys(OPT).concat(Object.keys(ALIAS))) {
      const pos = summary.lastIndexOf(cand);
      if (pos > bestPos) { bestPos = pos; best = cand; }
    }
    if (best) { name = ALIAS[best] || best; source = 'summary'; }
  }

  if (!name) {
    const links = f.issuelinks || [];
    const ordered = links.filter(l => l.type && l.type.id === '10079').concat(links.filter(l => !(l.type && l.type.id === '10079')));
    for (const l of ordered) {
      const other = l.inwardIssue || l.outwardIssue;
      if (!other) continue;
      const proj = other.key.split('-')[0];
      if (KEYMAP[proj]) { name = KEYMAP[proj]; source = 'linked ' + other.key; break; }
    }
  }

  if (!name) {
    for (const [re, opt] of WORDS) {
      if (re.test(summary)) { name = opt; source = 'product name in summary'; break; }
    }
  }

  if (!name) { name = '[IU Internationalization]'; source = 'fallback'; }

  out.push({ json: { key: issue.key, summary, futuremediaProject: name, optionId: OPT[name], source } });
}
return out;

